package app

const pageHTML = `
{{define "head"}}<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Restic Backup Validator</title><link rel="stylesheet" href="/style.css"></head><body><header><div class="brand"><span class="mark">✓</span><div><strong>Restic Backup Validator</strong><small>Version {{.Version}}</small></div></div><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="ghost" type="submit">Abmelden</button></form></header><main>{{end}}
{{define "foot"}}</main><footer>Prüfergebnisse sind nur nach OIDC-Anmeldung sichtbar.</footer></body></html>{{end}}
{{define "index"}}{{template "head" .}}
<section class="heading"><div><p class="eyebrow">Übersicht</p><h1>Backup-Prüfungen</h1><p>Aktualität, Integrität und eine echte Test-Wiederherstellung für jedes Repository.</p></div>{{if .Admin}}<a class="button" href="/repository">Repository hinzufügen</a>{{end}}</section>
<section class="panel"><div class="panel-head"><h2>Repositories</h2><span class="count">{{len .Repos}}</span></div>{{if .Repos}}<div class="table-wrap"><table><thead><tr><th>Name</th><th>Repository</th><th>Zeitplan</th><th>Nächster Teil</th><th>Status</th><th>Aktion</th></tr></thead><tbody>{{range .Repos}}<tr><td><strong>{{.Name}}</strong>{{if not .Enabled}}<small>Deaktiviert</small>{{end}}</td><td class="mono location">{{.Location}}</td><td><span class="mono">{{.Schedule}}</span><small>{{.Timezone}}</small></td><td class="mono">{{.NextSubset}}/{{.SubsetTotal}}</td><td>{{if index $.Active .ID}}<span class="badge running">Läuft</span>{{else}}<span class="badge idle">Bereit</span>{{end}}</td><td class="actions"><form method="post" action="/run"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><button type="submit" class="small">Jetzt prüfen</button></form>{{if $.Admin}}<a class="text-link" href="/repository?id={{.ID}}">Bearbeiten</a>{{end}}</td></tr>{{end}}</tbody></table></div>{{else}}<p class="empty">Noch keine Repositories angelegt. Ein Mitglied der Gruppe <code>backup_admin</code> kann das erste hinzufügen.</p>{{end}}</section>
<section class="panel"><div class="panel-head"><h2>Prüfprotokoll</h2><span class="muted">Letzte 100 Läufe</span></div>{{if .Runs}}<div class="table-wrap"><table><thead><tr><th>Zeitpunkt</th><th>Repository</th><th>Auslöser</th><th>Dauer</th><th>Teil</th><th>Ergebnis und Fehler</th></tr></thead><tbody>{{range .Runs}}<tr><td class="mono">{{.Started.Format "02.01.2006 15:04:05 MST"}}</td><td class="mono">{{.RepoID}}</td><td>{{.Trigger}}</td><td>{{.DurationMS}} ms</td><td class="mono">{{.Subset}}</td><td>{{if eq .Result "ok"}}<span class="badge ok">Erfolgreich</span>{{else}}<span class="badge failed">Fehler</span><details><summary>Details</summary><pre>{{.Error}}{{if .NotificationError}}
Discord: {{.NotificationError}}{{end}}</pre></details>{{end}}</td></tr>{{end}}</tbody></table></div>{{else}}<p class="empty">Noch keine Prüfläufe vorhanden.</p>{{end}}</section>
{{if .Admin}}<section class="panel settings"><div><h2>Discord-Alarm</h2><p>Der Webhook wird verschlüsselt gespeichert und nach dem Speichern nicht mehr angezeigt. {{if .WebhookSet}}Ein Webhook ist eingerichtet.{{else}}Noch kein Webhook eingerichtet.{{end}}</p></div><form method="post" action="/webhook"><input type="hidden" name="csrf" value="{{.CSRF}}"><label for="webhook">Neuer Webhook</label><input id="webhook" name="webhook" type="password" autocomplete="off" placeholder="https://discord.com/api/webhooks/…"><button type="submit">Webhook speichern</button></form></section>{{end}}
{{template "foot" .}}{{end}}
{{define "edit"}}{{template "head" .}}<section class="heading"><div><p class="eyebrow">Konfiguration</p><h1>{{if .Repo.ID}}Repository bearbeiten{{else}}Repository hinzufügen{{end}}</h1><p>Zugangsdaten werden verschlüsselt gespeichert. Leere Secret-Felder behalten beim Bearbeiten ihren bisherigen Wert.</p></div><a class="button secondary" href="/">Zur Übersicht</a></section>
{{if .Error}}<div class="error" role="alert">{{.Error}}</div>{{end}}
<form class="panel form-grid" method="post" action="/repository/save" autocomplete="off"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.Repo.ID}}">
<div class="field"><label for="name">Name</label><input id="name" name="name" value="{{.Repo.Name}}" maxlength="100" required></div>
<div class="field"><label for="location">Restic-Repository</label><input id="location" name="location" value="{{.Repo.Location}}" maxlength="2048" placeholder="/repositories/example oder s3:…" required></div>
<div class="field"><label for="password">Restic-Passwort {{if .Repo.HasPassword}}(gespeichert){{end}}</label><input id="password" name="password" type="password" autocomplete="new-password" placeholder="{{if .Repo.HasPassword}}Unverändert lassen{{else}}Passwort eingeben{{end}}"></div>
<div class="field"><label for="backend_env">Backend-Zugangsdaten {{if .Repo.HasBackendEnv}}(gespeichert){{end}}</label><textarea id="backend_env" name="backend_env" rows="3" placeholder="AWS_ACCESS_KEY_ID=…&#10;AWS_SECRET_ACCESS_KEY=…"></textarea><small>KEY=WERT pro Zeile. AWS_, B2_, AZURE_, GOOGLE_ und RCLONE_ sind erlaubt.</small></div>
<div class="field"><label for="schedule">Cron-Zeitplan (5 Felder)</label><input id="schedule" name="schedule" value="{{.Repo.Schedule}}" required><small>Beispiel: 0 3 * * * für täglich 03:00.</small></div>
<div class="field"><label for="timezone">Zeitzone</label><input id="timezone" name="timezone" value="{{.Repo.Timezone}}" required><small>IANA-Name, zum Beispiel Europe/Berlin.</small></div>
<div class="field"><label for="max_age_hours">Maximales Snapshot-Alter (Stunden)</label><input id="max_age_hours" name="max_age_hours" type="number" min="1" max="8760" value="{{.Repo.MaxAgeHours}}" required></div>
<div class="field"><label for="subset_total">Daten-Teile</label><input id="subset_total" name="subset_total" type="number" min="1" max="365" value="{{.Repo.SubsetTotal}}" required></div>
<div class="field"><label for="test_path">Testdatei im Snapshot</label><input id="test_path" name="test_path" value="{{.Repo.TestPath}}" placeholder="/backup/validator-marker.txt" required></div>
<div class="field"><label for="test_sha256">Erwarteter SHA-256-Hash</label><input id="test_sha256" name="test_sha256" value="{{.Repo.TestSHA256}}" pattern="[a-fA-F0-9]{64}" required></div>
<div class="field"><label for="host_filter">Host-Filter (optional)</label><input id="host_filter" name="host_filter" value="{{.Repo.HostFilter}}"></div>
<div class="field"><label for="path_filter">Snapshot-Pfad-Filter (optional)</label><input id="path_filter" name="path_filter" value="{{.Repo.PathFilter}}"></div>
<div class="field"><label for="tag_filter">Tag-Filter (optional)</label><input id="tag_filter" name="tag_filter" value="{{.Repo.TagFilter}}"></div>
<div class="field checkbox"><label><input name="enabled" type="checkbox" {{if .Repo.Enabled}}checked{{end}}> Automatische Prüfung aktiv</label></div>
<div class="form-actions"><button type="submit">Speichern</button><a class="button secondary" href="/">Abbrechen</a></div></form>
{{if .Repo.ID}}<form method="post" action="/repository/delete" class="delete-form"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.Repo.ID}}"><button type="submit" class="danger">Repository löschen</button></form>{{end}}
{{template "foot" .}}{{end}}`
